const messages = $('Get a thread').first().json.messages || [];
const attachments = [];
const vus = new Set();

const typesAutorises = [
  'application/pdf',
  'image/jpeg', 
  'image/png',
  'image/jpg',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
];

function extractAttachments(parts, messageId) {
  if (!parts) return;
  for (const part of parts) {
    if (part.body?.attachmentId && part.filename && typesAutorises.includes(part.mimeType)) {
      if (!vus.has(part.filename)) {
        vus.add(part.filename);
        attachments.push({
          messageId,
          attachmentId: part.body.attachmentId,
          filename: part.filename,
          mimeType: part.mimeType
        });
      }
    }
    if (part.parts) extractAttachments(part.parts, messageId);
  }
}

for (const msg of messages) {
  if (msg.payload?.parts) extractAttachments(msg.payload.parts, msg.id);
}

if (attachments.length === 0) return [{ json: { statut: 'aucune_piece_jointe' } }];
return attachments.map(att => ({ json: att }));

const items = $input.all();
const hashVus = new Set();
const resultats = [];

for (const item of items) {
  const hash = item.json.hash || '';
  if (hashVus.has(hash)) continue;
  hashVus.add(hash);

  resultats.push({
    json: {
      filename: item.json.filename || 'document',
      mimeType: item.json.mimeType || '',
      hash,
      texteOCR: item.json.text || '',
      messageId: item.json.messageId || '',
      attachmentId: item.json.attachmentId || '',
      malware: item.json.malware || false,
      statut: 'valide'
    }
  });
}

if (resultats.length === 0) {
  return [{ json: { statut: 'aucun_fichier_valide' } }];
}
return resultats;

function getBody(payload) {
  if (!payload) return '';

  if (payload.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf-8');
  }

  if (payload.parts) {
    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        return Buffer.from(part.body.data, 'base64').toString('utf-8');
      }
    }
    for (const part of payload.parts) {
      const nested = getBody(part);
      if (nested) return nested;
    }
  }

  return '';
}

const messages = $('Get a thread').first().json.messages || [];
const texteEmails = messages.map(m => {
  const h = m.payload?.headers || [];
  const de = h.find(x => x.name === 'From')?.value || '';
  const sujet = h.find(x => x.name === 'Subject')?.value || '';
  const corps = getBody(m.payload) || m.snippet || '';
  return `De: ${de} | Objet: ${sujet}\n${corps}`;
}).join('\n---\n');

const items = $input.all();
const hashVus = new Set();
const fichiers = [];
const today = new Date().toISOString().split('T')[0];
const nomSociete = 'SOCIETE';

for (const item of items) {
  const hash = item.json.hash || '';
  if (hashVus.has(hash)) continue;
  hashVus.add(hash);

  fichiers.push({
    filename: `${today}_${nomSociete}_${item.json.filename || 'document'}`,
    filenameOriginal: item.json.filename || 'document',
    mimeType: item.json.mimeType || '',
    hash,
    texteOCR: item.json.text || item.json.texteOCR || '',
    messageId: item.json.messageId || '',
    attachmentId: item.json.attachmentId || '',
    malware: item.json.malware || false,
    statut: 'valide'
  });
}

const texteOCR = fichiers.map((f, i) =>
  `=== Fichier ${i+1} : ${f.filenameOriginal} ===\n${f.texteOCR}`
).join('\n\n');

const clientId = `CLI-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

return [{ json: { texteEmails, texteOCR, fichiers, clientId, today } }];

// Node: JS-Filtrer Nouveaux Fichiers
// Mode : Run Once for All Items
// Le hash Gmail est maintenant calculé sur le PDF décodé = identique au md5Checksum Drive

// ---------- MD5 des fichiers existants dans Drive ----------
const driveResponse = $('HTTP Request1').first().json;
const existingFiles = driveResponse.files || [];
const existingMD5s = new Set(existingFiles.map(f => f.md5Checksum).filter(Boolean));

// ---------- Nouveaux fichiers depuis JS-Dédupliquer ----------
const newFiles = $('JS-Dédupliquer ').all();

// ---------- Déduplication ----------
const seenHashes = new Set();
const uniqueNewFiles = [];

for (const item of newFiles) {
  const f = item.json;
  const hash = f.hash; // MD5 du PDF décodé = même que Drive

  if (!hash) continue;

  // Doublon parmi les nouveaux ?
  if (seenHashes.has(hash)) continue;
  seenHashes.add(hash);

  // Déjà présent dans Drive ?
  if (existingMD5s.has(hash)) continue;

  uniqueNewFiles.push({ json: { ...f, hasNewFiles: true } });
}

// ---------- Sortie ----------
if (uniqueNewFiles.length === 0) {
  return [{ json: { hasNewFiles: false, count: 0 } }];
}

return uniqueNewFiles;

// Node: JS-Fusionner Champs Vides
// Mode : Run Once for All Items
// Règle : 
//   - Complète les champs vides/FALSE avec les nouvelles valeurs
//   - Met à jour les champs qui ont changé (differences détectées par JS-Détecter Doublon)

const detected = $('Js detecter doublon').first().json;
const oldData = detected.existingRowData || {};
const differences = detected.differences || [];

function isEmptyValue(v) {
  if (v === undefined || v === null) return true;
  const s = String(v).trim().toUpperCase();
  return s === '' || s === 'FALSE' || s === 'NON RENSEIGNÉ';
}

const fieldsToMerge = ['nom_société', 'email_client', 'siret', 'parcours', 'paie', 'juridique'];
const merged = { ...oldData };
const changedFields = [];

// Construire un dictionnaire des champs qui ont changé
const diffMap = {};
for (const diff of differences) {
  diffMap[diff.field] = diff.nouveau;
}

for (const field of fieldsToMerge) {
  const oldVal = oldData[field];
  const newVal = detected[field] !== undefined
    ? detected[field]
    : detected[field.replace('é', 'e').replace('è', 'e')];

  // Cas 1 : champ vide/FALSE → compléter avec la nouvelle valeur
  if (isEmptyValue(oldVal) && !isEmptyValue(newVal)) {
    merged[field] = newVal;
    changedFields.push(field);
  }
  // Cas 2 : champ différent détecté par differences → remplacer par la nouvelle valeur
  else if (diffMap[field] !== undefined) {
    merged[field] = diffMap[field];
    changedFields.push(field);
  }
}

return {
  json: {
    ...merged,
    existingRowNumber: detected.existingRowNumber,
    changedFields,
    hasChanges: changedFields.length > 0
  }
};

// Node: JS-Décoder pour Hash
// À insérer entre "HTTP-Télécharger Binaire Gmail" et "Crypto-Hash MD5 Fichier"
// Décode le base64 Gmail en vrai binaire PDF, pour que le MD5 corresponde à celui de Drive

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const gmailResponse = JSON.parse(buffer.toString('utf-8'));

  const base64Standard = gmailResponse.data.replace(/-/g, '+').replace(/_/g, '/');
  const pdfBuffer = Buffer.from(base64Standard, 'base64');

  results.push({
    json: { ...items[i].json },
    binary: {
      data: await this.helpers.prepareBinaryData(
        pdfBuffer,
        items[i].json.filename || 'document.pdf',
        items[i].json.mimeType || 'application/pdf'
      )
    }
  });
}

return results;

return {
  date: new Date().toISOString().split('T')[0],
  ThreadID: $('Get a thread').first().json.id

};

// ─────────────────────────────────────────────
// JS - Détecteur Doublon
// ─────────────────────────────────────────────
const rawOutput = $('AI Agent-Extraction Client').first().json.output;
let cleanOutput = rawOutput;
if (typeof rawOutput === 'string') {
  cleanOutput = rawOutput.replace(/```json\s*|```/g, '').trim();
}
const newItem = typeof cleanOutput === 'string' ? JSON.parse(cleanOutput) : cleanOutput;

const INVALID_VALUES = ['Erreur', 'Non renseigné', ''];

const existingClients = $('Lire Clients Sheet').all();
let matchedRow = null;
let matchReason = null;
for (const client of existingClients) {
  const row = client.json;
  if (row.siret && newItem.siret &&
      !INVALID_VALUES.includes(row.siret) && !INVALID_VALUES.includes(newItem.siret) &&
      String(row.siret).trim() === String(newItem.siret).trim()) {
    matchedRow = client;
    matchReason = 'siret';
    break;
  }
  if (row.email_client && newItem.email_client &&
      !INVALID_VALUES.includes(row.email_client) && !INVALID_VALUES.includes(newItem.email_client) &&
      row.email_client.toLowerCase().trim() === newItem.email_client.toLowerCase().trim()) {
    matchedRow = client;
    matchReason = 'email_client';
    break;
  }
  if (row.nom_société && newItem.nom_societe &&
      row.nom_société.toLowerCase().trim() === newItem.nom_societe.toLowerCase().trim()) {
    matchedRow = client;
    matchReason = 'nom_société';
    break;
  }
}

const fieldsToCompare = ['nom_société', 'email_client', 'siret', 'parcours', 'paie', 'juridique'];
const differences = [];
const finalItem = { ...newItem };

if (matchedRow) {
  const oldData = matchedRow.json;
  for (const field of fieldsToCompare) {
    const oldVal = String(oldData[field] ?? '').trim();
    const newFieldKey = field === 'nom_société' ? 'nom_societe' : field;
    const newVal = String(newItem[newFieldKey] ?? '').trim();

    if (oldVal === 'Erreur' && newVal !== '' && newVal !== 'undefined' && newVal !== 'Erreur') {
      differences.push({ field, ancien: oldVal, nouveau: newVal, raison: 'correction_erreur' });
      continue;
    }
    if (newVal === 'Erreur' && oldVal !== '' && oldVal !== 'Erreur') {
      finalItem[newFieldKey] = oldVal;
      continue;
    }
    if (oldVal !== newVal && newVal !== '' && newVal !== 'undefined') {
      differences.push({ field, ancien: oldVal, nouveau: newVal });
    }
  }
}

return [{
  json: {
    ...finalItem,
    isDuplicate: !!matchedRow,
    matchReason: matchReason,
    existingRowNumber: matchedRow ? matchedRow.json.row_number : null,
    existingRowData: matchedRow ? matchedRow.json : null,
    differences: differences
  }
}];

return {
  json: {
    date: new Date().toISOString().split('T')[0],
    ThreadID:$('Get a thread').first().json.id// adapte selon le nom exact du champ dans ton item d'entrée
  }
};
